package buildinfo

import (
	"fmt"
	"go/ast"
	"go/parser"
	"go/token"
	"sort"
	"strconv"
	"strings"
)

// The embedded-Hub build form (-tags inprochost, docs/04 M1) cannot carry the
// vendored generated files: the Hub's own packages (github.com/c1ayooo/cyber/aop)
// register the same protobuf descriptors and message names in the global
// registry, and two registrations of one proto file panic at init. The
// resolution is that under the tag, every vendored generated package becomes a
// forwarding alias package: `type X = cyber/aop.X` for every exported
// declaration, so exactly one copy of each generated type exists in the binary
// and the vendored files are excluded from the build.
//
// The default (exec) build is untouched: the vendored files carry
// `//go:build !inprochost` and the client code compiles against them as before.
// The alias files are generated by the sync pipeline (AOPProtoAliasContent),
// so both forms always describe the same harness sources.

// aopAliasTarget is the fork package a vendored generated package forwards to.
type aopAliasTarget struct {
	// ImportPath is the fork package's full import path.
	ImportPath string
	// PackageName is that fork package's Go package clause (the name the alias
	// file's qualifier uses).
	PackageName string
}

// aopAliasTargets maps a vendored directory (slash path, no .go suffix) to the
// fork package whose generated file it was vendored from. Derived from
// AOPProtoFiles' HarnessPath/VendoredPath pairs: every vendored generated
// package has exactly one fork package.
func aopAliasTargets() map[string]aopAliasTarget {
	m := map[string]aopAliasTarget{}
	for _, f := range AOPProtoFiles {
		dir := func(p string) string {
			i := strings.LastIndexByte(p, '/')
			return p[:i]
		}
		vdir, hdir := dir(f.VendoredPath), dir(f.HarnessPath)
		pkg := aopAliasTargetForHarnessDir(hdir)
		if _, seen := m[vdir]; seen && m[vdir] != pkg {
			// One vendored package maps to two fork packages: the alias scheme
			// does not fit. This is a design error caught here rather than a
			// silent partial forwarding.
			panic("aopalias: " + vdir + " maps to both " + m[vdir].ImportPath + " and " + pkg.ImportPath)
		}
		m[vdir] = pkg
	}
	return m
}

// aopAliasTargetForHarnessDir names the fork package that owns one generated
// file directory. The fork layout is: aop/*.pb.go (package aop),
// aop/<sub>/protocol.pb.go (package sub), core/types/*.pb.go (package types)
// and exts/guardrail/guardrail.pb.go (package guardrail).
func aopAliasTargetForHarnessDir(dir string) aopAliasTarget {
	switch {
	case dir == "aop":
		return aopAliasTarget{ImportPath: harnessAOPProto, PackageName: "aop"}
	case strings.HasPrefix(dir, "aop/"):
		name := dir[len("aop/"):]
		return aopAliasTarget{ImportPath: harnessAOPProto + "/" + name, PackageName: name}
	case dir == "core/types":
		return aopAliasTarget{ImportPath: harnessModulePath + "/core/types", PackageName: "types"}
	case dir == "exts/guardrail":
		return aopAliasTarget{ImportPath: harnessModulePath + "/exts/guardrail", PackageName: "guardrail"}
	default:
		panic("aopalias: unknown harness generated directory " + dir)
	}
}

// harnessModulePath is the fork module's path (never published under it, hence
// the go.mod replace — the alias imports resolve through that replace).
const harnessModulePath = "github.com/c1ayooo/cyber"

// AOPAliasPaths lists the alias file (vendored path) each vendored generated
// package gets under the tag, keyed by the vendored directory.
func AOPAliasPaths() map[string]string {
	out := map[string]string{}
	for dir := range aopAliasTargets() {
		out[dir] = dir + "/alias_gen.go"
	}
	return out
}

// AOPAliasInput is one fork generated file with its bytes, belonging to the
// vendored package that forwards to it.
type AOPAliasInput struct {
	File    AOPProtoFile
	Content []byte
}

// AOPAliasContent parses the fork generated files of one vendored package and
// renders that package's forwarding alias file: every exported type, variable,
// constant and function across all of the fork package's generated files
// becomes a `name = fork.name` declaration; unexported runtime state (rawDesc,
// type builders) stays private to the fork packages, which is the point: one
// registration, one copy of the types.
func AOPAliasContent(inputs []AOPAliasInput) ([]byte, error) {
	if len(inputs) == 0 {
		return nil, fmt.Errorf("alias 输入为空")
	}
	target := aopAliasTargets()[mustVendoredDir(inputs[0].File.VendoredPath)]

	type decl struct{ kind, name string }
	seen := map[string]bool{}
	var names []decl
	for _, input := range inputs {
		fset := token.NewFileSet()
		astFile, err := parser.ParseFile(fset, input.File.HarnessPath, input.Content, 0)
		if err != nil {
			return nil, fmt.Errorf("解析 %s：%w", input.File.HarnessPath, err)
		}
		for _, d := range astFile.Decls {
			switch d := d.(type) {
			case *ast.GenDecl:
				for _, spec := range d.Specs {
					switch spec := spec.(type) {
					case *ast.TypeSpec:
						if spec.Name.IsExported() && !seen[spec.Name.Name] {
							seen[spec.Name.Name] = true
							names = append(names, decl{declKeyword(d.Tok), spec.Name.Name})
						}
					case *ast.ValueSpec:
						for _, id := range spec.Names {
							if id.IsExported() && !seen[id.Name] {
								seen[id.Name] = true
								names = append(names, decl{declKeyword(d.Tok), id.Name})
							}
						}
					}
				}
			case *ast.FuncDecl:
				if d.Recv == nil && d.Name.IsExported() && !seen[d.Name.Name] {
					seen[d.Name.Name] = true
					names = append(names, decl{"func", d.Name.Name})
				}
			}
		}
	}
	if len(names) == 0 {
		return nil, fmt.Errorf("%s 没有可转发的导出声明", inputs[0].File.HarnessPath)
	}
	sort.Slice(names, func(i, j int) bool { return names[i].name < names[j].name })

	var b strings.Builder
	b.WriteString("// Code generated by the AOP sync pipeline (internal/buildinfo); DO NOT EDIT.\n")
	b.WriteString("//\n")
	b.WriteString("// Forwarding aliases for the embedded-Hub build form: every exported\n")
	b.WriteString("// declaration of the vendored generated package resolves to the fork's\n")
	b.WriteString("// single registered copy (" + target.ImportPath + "), so the global protobuf\n")
	b.WriteString("// registry holds one descriptor set instead of two. The vendored files\n")
	b.WriteString("// are excluded under this tag (//go:build !inprochost).\n\n")
	b.WriteString("//go:build inprochost\n\n")
	b.WriteString("package " + vendoredPackageName(inputs[0].File) + "\n\n")
	b.WriteString("import " + target.PackageName + " " + strconv.Quote(target.ImportPath) + "\n\n")
	for _, n := range names {
		b.WriteString(n.kind + " " + n.name + " = " + target.PackageName + "." + n.name + "\n")
	}
	return []byte(b.String()), nil
}

func mustVendoredDir(vendoredPath string) string {
	i := strings.LastIndexByte(vendoredPath, '/')
	if i < 0 {
		panic("aopalias: vendored path without a directory: " + vendoredPath)
	}
	return vendoredPath[:i]
}

func vendoredPackageName(file AOPProtoFile) string {
	if pkg := strings.TrimSpace(file.VendoredPackage); pkg != "" {
		return pkg
	}
	// The vendored twin's package clause: generated protobuf packages use their
	// directory name (pb, operation, …).
	dir := mustVendoredDir(file.VendoredPath)
	if j := strings.LastIndexByte(dir, '/'); j >= 0 {
		return dir[j+1:]
	}
	return dir
}

func declKeyword(tok token.Token) string {
	switch tok {
	case token.TYPE:
		return "type"
	case token.VAR:
		return "var"
	case token.CONST:
		return "const"
	}
	return "var"
}
